import InputText from 'primevue/inputtext';

export default {
    name: "Detail",
    data() {
      return {};
    },
    components: {
      InputText
    },
    beforeRouteLeave(to, from, next) {
      history.replaceState(null, '', '/'); // Clears the history entry
      next();
    }
  };
